def get_edge_values(type_name: str) -> list:
    edge_map = {
        'number': [0, 1, -1, 999999, -999999],
        'string': ['', 'a', 'hello world', 'x' * 100],
        'array': [[], [1], [1, 2, 3], list(range(100))],
        'boolean': [True, False],
        'object': [{}, {'key': 'value'}, None],
    }
    return edge_map.get(type_name, [None])

def get_error_values(type_name: str) -> list:
    error_map = {
        'number': ['string', None, [], True],
        'string': [123, None, [], True],
        'array': ['string', 123, None, {}],
        'boolean': ['true', 0, None, 'yes'],
        'object': ['string', 123, True],
    }
    return error_map.get(type_name, [None])

def generate_test_cases(signature: dict) -> list:
    test_cases = []
    fn_name = signature['name']
    params = signature.get('params', [])

    if not params:
        test_cases.append({
            'category': 'normal',
            'name': f'{fn_name} should execute without arguments',
            'args': [],
        })
        return test_cases

    # Normal cases
    normal_values = {'number': [1, 2, 42], 'string': ['hello', 'test'], 'array': [[1,2,3]], 'boolean': [True], 'object': [{'key': 'val'}]}
    for i, param in enumerate(params):
        vals = normal_values.get(param['type'], ['test'])
        for val in vals[:2]:
            args = []
            for j, p in enumerate(params):
                if j == i:
                    args.append(val)
                else:
                    defaults = {'number': 1, 'string': 'test', 'array': [1], 'boolean': True, 'object': {}}
                    args.append(defaults.get(p['type'], None))
            test_cases.append({
                'category': 'normal',
                'name': f'{fn_name} with {param["name"]}={repr(val)}',
                'args': args,
            })

    # Edge cases
    for i, param in enumerate(params):
        for val in get_edge_values(param['type'])[:3]:
            args = []
            for j, p in enumerate(params):
                if j == i:
                    args.append(val)
                else:
                    defaults = {'number': 1, 'string': 'test', 'array': [1], 'boolean': True, 'object': {}}
                    args.append(defaults.get(p['type'], None))
            test_cases.append({
                'category': 'edge',
                'name': f'{fn_name} edge case: {param["name"]}={repr(val)}',
                'args': args,
            })

    # Error cases
    for i, param in enumerate(params):
        for val in get_error_values(param['type'])[:2]:
            args = []
            for j, p in enumerate(params):
                if j == i:
                    args.append(val)
                else:
                    defaults = {'number': 1, 'string': 'test', 'array': [1], 'boolean': True, 'object': {}}
                    args.append(defaults.get(p['type'], None))
            test_cases.append({
                'category': 'error',
                'name': f'{fn_name} error case: {param["name"]}={repr(val)} (wrong type)',
                'args': args,
            })

    return test_cases

