function getEdgeValues(typeName) {
  const map = {
    number: [0, 1, -1, Number.MAX_SAFE_INTEGER, -Number.MAX_SAFE_INTEGER],
    string: ['', 'a', 'hello world', 'x'.repeat(100)],
    array: [[], [1], [1,2,3], Array.from({length:100}, (_,i) => i)],
    boolean: [true, false],
    object: [{}, {key: 'value'}, null],
  };
  return map[typeName] || [null];
}

function getErrorValues(typeName) {
  const map = {
    number: ['string', null, [], true],
    string: [123, null, [], true],
    array: ['string', 123, null, {}],
    boolean: ['true', 0, null],
    object: ['string', 123, true],
  };
  return map[typeName] || [null];
}

function generateTestCases(signature) {
  const { name: fnName, params = [] } = signature;
  const testCases = [];
  const defaults = { number: 1, string: 'test', array: [1], boolean: true, object: {} };

  if (!params.length) {
    return [{ category: 'normal', name: `${fnName} should execute without arguments`, args: [] }];
  }

  const normals = { number: [1,2,42], string: ['hello','test'], array: [[1,2,3]], boolean: [true], object: [{key:'val'}] };

  for (let i = 0; i < params.length; i++) {
    const vals = (normals[params[i].type] || ['test']).slice(0, 2);
    for (const val of vals) {
      const args = params.map((p, j) => j === i ? val : defaults[p.type]);
      testCases.push({ category: 'normal', name: `${fnName} with ${params[i].name}=${JSON.stringify(val)}`, args });
    }
  }

  for (let i = 0; i < params.length; i++) {
    for (const val of getEdgeValues(params[i].type).slice(0, 3)) {
      const args = params.map((p, j) => j === i ? val : defaults[p.type]);
      testCases.push({ category: 'edge', name: `${fnName} edge: ${params[i].name}=${JSON.stringify(val)}`, args });
    }
  }

  for (let i = 0; i < params.length; i++) {
    for (const val of getErrorValues(params[i].type).slice(0, 2)) {
      const args = params.map((p, j) => j === i ? val : defaults[p.type]);
      testCases.push({ category: 'error', name: `${fnName} error: ${params[i].name}=${JSON.stringify(val)}`, args });
    }
  }

  return testCases;
}
